from pathlib import Path
import ast
import base64
import hashlib
import re
import shutil
import zlib

DISPATCH = Path("wa_backend/api/dispatch.py")
SCHEMAS = Path("wa_backend/schemas.py")
BACKUP_DIR = Path(".patch_backups/DISPATCH_FINAL_INTEGRITY_GATE")
MARKER = "# PATCH: DISPATCH_FINAL_INTEGRITY_GATE"
EXPECTED_DISPATCH_SHA256 = "a943eec3777ac8c4224351d31347f3fc4d42242b7637cd28087352197624d423"
PATCHED_DISPATCH_SHA256 = "965209adc94ac7eb0352d1308a7a2c45a936ccc5e942e4c955324f5bceebcca4"

_DISPATCH_ZLIB_B64 = """"""

LEGACY = (
    "MainWarehouse",
    "VehicleLoad",
    "SessionInventory",
    "InventoryTransfer",
    "WarehouseLedger",
    "InventoryLedger",
)

def sha_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()

def _class_fields(tree: ast.AST, class_name: str) -> set[str]:
    for node in tree.body:
        if isinstance(node, ast.ClassDef) and node.name == class_name:
            fields = set()
            for stmt in node.body:
                if isinstance(stmt, ast.AnnAssign) and isinstance(stmt.target, ast.Name):
                    fields.add(stmt.target.id)
                elif isinstance(stmt, ast.Assign):
                    for target in stmt.targets:
                        if isinstance(target, ast.Name):
                            fields.add(target.id)
            return fields
    raise RuntimeError(f"Missing class: {class_name}")

def _unused_imports(source: str) -> list[str]:
    tree = ast.parse(source)
    imported = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imported.append(alias.asname or alias.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                imported.append(alias.asname or alias.name)
    used = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }
    return sorted({name for name in imported if name not in used})

def _internal_signature_mismatches(source: str):
    tree = ast.parse(source)
    defs = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            allowed = {
                arg.arg
                for arg in [*node.args.args, *node.args.kwonlyargs]
            }
            defs[node.name] = (allowed, node.args.kwarg is not None)

    bad = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not isinstance(node.func, ast.Name) or node.func.id not in defs:
            continue
        allowed, has_varkw = defs[node.func.id]
        if has_varkw:
            continue
        unknown = [
            kw.arg
            for kw in node.keywords
            if kw.arg is not None and kw.arg not in allowed
        ]
        if unknown:
            bad.append((node.lineno, node.func.id, unknown))
    return bad

def verify_dispatch(source: str) -> None:
    compile(source, str(DISPATCH), "exec")
    tree = ast.parse(source)

    if MARKER not in source:
        raise RuntimeError("Final integrity marker missing.")

    required = (
        "async def _dispatch_assert_vehicle_custody_reconciled(",
        "async def _dispatch_vehicle_location_ids(",
        "async def _dispatch_driver_shortage_cash_map(",
        'operation="DISPATCH_ADJUST_ROUTE_INVENTORY"',
        "begin_idempotent_operation(",
        "complete_idempotent_operation(",
        'SessionInventorySnapshot.stock_status == "AVAILABLE"',
        '"inventory_shortage_cash": str(shortage_cash)',
        "allowed_work_session_id=(int(session.id) if session is not None else None)",
        "source_is_vehicle == destination_is_vehicle",
        "requires_live_assets = (",
        "admin=current_admin,",
        "session=active_session,",
        'route.status != "active"',
    )
    for token in required:
        if token not in source:
            raise RuntimeError(f"Required invariant missing: {token}")

    for symbol in LEGACY:
        if re.search(rf"\\b{re.escape(symbol)}\\b", source):
            raise RuntimeError(f"Legacy inventory symbol remains: {symbol}")

    forbidden = (
        r"InventoryBalance\s*\(",
        r"\.on_hand_quantity\s*=",
        r"\.reserved_quantity\s*=",
        r"update\s*\(\s*InventoryBalance",
        r"delete\s*\(\s*InventoryBalance",
    )
    for pattern in forbidden:
        if re.search(pattern, source):
            raise RuntimeError(f"Direct InventoryBalance mutation detected: {pattern}")

    mismatches = _internal_signature_mismatches(source)
    if mismatches:
        raise RuntimeError(f"Internal call/signature mismatch: {mismatches[:5]}")

    unused = _unused_imports(source)
    if unused:
        raise RuntimeError(f"Unused imports remain in dispatch.py: {unused}")

def patch_schemas(source: str) -> str:
    if "from uuid import UUID" not in source:
        raise RuntimeError("schemas.py UUID import missing; baseline differs.")

    finance_field = (
        '    cash_from_debts: Annotated[str, BeforeValidator(clean_finance_str)] = "0.0"\n'
    )
    if "inventory_shortage_cash:" not in source:
        if source.count(finance_field) != 1:
            raise RuntimeError("AdminFinancials anchor changed.")
        source = source.replace(
            finance_field,
            finance_field
            + '    inventory_shortage_cash: Annotated[str, BeforeValidator(clean_finance_str)] = "0.0"\n',
            1,
        )

    adjust_anchor = (
        "class AdjustRouteInventoryRequest(RequestModel):\n"
        "    deltas: List[InventoryAdjustmentDelta] = Field(\n"
    )
    if re.search(
        r"class AdjustRouteInventoryRequest\(RequestModel\):\s+request_id:\s*UUID",
        source,
    ) is None:
        if source.count(adjust_anchor) != 1:
            raise RuntimeError("AdjustRouteInventoryRequest anchor changed.")
        source = source.replace(
            adjust_anchor,
            "class AdjustRouteInventoryRequest(RequestModel):\n"
            "    request_id: UUID\n"
            "    deltas: List[InventoryAdjustmentDelta] = Field(\n",
            1,
        )
    return source

def verify_schemas(source: str) -> None:
    compile(source, str(SCHEMAS), "exec")
    tree = ast.parse(source)
    finance = _class_fields(tree, "AdminFinancials")
    adjust = _class_fields(tree, "AdjustRouteInventoryRequest")
    if "inventory_shortage_cash" not in finance:
        raise RuntimeError("AdminFinancials.inventory_shortage_cash missing.")
    if "request_id" not in adjust:
        raise RuntimeError("AdjustRouteInventoryRequest.request_id missing.")

def main() -> None:
    if not DISPATCH.exists() or not SCHEMAS.exists():
        raise SystemExit("Run this patch from the project root containing wa_backend/.")

    current_dispatch = DISPATCH.read_text(encoding="utf-8")
    current_schemas = SCHEMAS.read_text(encoding="utf-8")

    if MARKER in current_dispatch:
        verify_dispatch(current_dispatch)
        verify_schemas(current_schemas)
        print("DISPATCH_FINAL_INTEGRITY_GATE_ALREADY_OK")
        return

    current_hash = sha_text(current_dispatch)
    if current_hash != EXPECTED_DISPATCH_SHA256:
        raise RuntimeError(
            "dispatch.py differs from the verified uploaded baseline; "
            f"expected {EXPECTED_DISPATCH_SHA256}, got {current_hash}. Aborting safely."
        )

    patched_dispatch = zlib.decompress(
        base64.b64decode(_DISPATCH_ZLIB_B64.encode("ascii"))
    ).decode("utf-8")
    if sha_text(patched_dispatch) != PATCHED_DISPATCH_SHA256:
        raise RuntimeError("Embedded dispatch payload hash mismatch.")

    patched_schemas = patch_schemas(current_schemas)

    verify_dispatch(patched_dispatch)
    verify_schemas(patched_schemas)

    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    dispatch_backup = BACKUP_DIR / "dispatch.py"
    schemas_backup = BACKUP_DIR / "schemas.py"
    if not dispatch_backup.exists():
        shutil.copy2(DISPATCH, dispatch_backup)
    if not schemas_backup.exists():
        shutil.copy2(SCHEMAS, schemas_backup)

    dispatch_tmp = DISPATCH.with_suffix(".py.tmp")
    schemas_tmp = SCHEMAS.with_suffix(".py.tmp")
    dispatch_tmp.write_text(patched_dispatch, encoding="utf-8", newline="\n")
    schemas_tmp.write_text(patched_schemas, encoding="utf-8", newline="\n")
    dispatch_tmp.replace(DISPATCH)
    schemas_tmp.replace(SCHEMAS)

    print("DISPATCH_FINAL_INTEGRITY_GATE_OK")
    print("VEHICLE_CUSTODY_OK: vehicle cannot be reassigned/mutated before prior inventory reconciliation")
    print("DELTA_IDEMPOTENCY_OK: adjust_inventory requires request_id and replays safely")
    print("RUNTIME_SIGNATURE_OK: _dispatch_absolute_targets call matches admin/session contract")
    print("FINANCIAL_VIEW_OK: dashboard/report/settlement include the same DRIVER_SHORTAGE amount")
    print("JARD_STATUS_OK: accountant compatibility check compares AVAILABLE Ending Snapshot only")
    print("HANDSHAKE_HISTORY_OK: transfer monitor resolves every historical VEHICLE location for the route vehicle")
    print("HISTORICAL_CLOSE_OK: inactive driver/vehicle do not block closing a bound historical route")
    print("LIVE_ASSET_OK: active routes/new inventory still require active driver, vehicle, and VEHICLE location")
    print("LIABILITY_VISIBILITY_OK: every financially unsettled session remains visible regardless of age/account status")
    print("UNDO_END_OK: reopen requires active driver + active route + active vehicle/location")
    print("TENANT_ENGINE_OK: no legacy inventory symbols; no direct InventoryBalance writes")
    print("FILES_CHANGED: wa_backend/api/dispatch.py + wa_backend/schemas.py")
    print("NEXT: py_compile + git diff --check + PostgreSQL hostile dispatch E2E")

if __name__ == "__main__":
    main()
